package webui

// stylesBuilder is the protocol browser, recipe builder and advanced studio; stylesCopyReduction is the copy-reduction pass (v44).
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesBuilder = `.protocol-browser{border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.protocol-browser>header{min-height:54px;display:flex;align-items:center;justify-content:space-between;padding:9px 13px;border-bottom:1px solid var(--line)}.protocol-browser>header>div{display:flex;align-items:center;gap:9px}.protocol-browser>header b{display:block;font-size:11px}.protocol-browser>header small{color:var(--muted);font-size:9px}.protocol-browser>nav{display:flex;overflow:auto;padding:7px}.protocol-browser>nav a{min-width:160px;display:grid;grid-template-columns:40px 1fr auto;align-items:center;gap:8px;padding:8px;border-radius:7px}.protocol-browser>nav a:hover,.protocol-browser>nav a.active{background:var(--surface-2)}.protocol-browser>nav a.active{box-shadow:inset 0 0 0 1px var(--accent);color:var(--accent)}.protocol-browser>nav a>b{height:31px;display:grid;place-items:center;border:1px solid var(--line);border-radius:6px;font-size:8px}.protocol-browser strong,.protocol-browser small{display:block}.protocol-browser strong{font-size:10px}.protocol-browser small{max-width:95px;overflow:hidden;color:var(--muted);font-size:8px;text-overflow:ellipsis;white-space:nowrap}.protocol-browser i{font-style:normal}.recipe-workspace{margin-top:12px;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.recipe-toolbar{min-height:70px;display:flex;align-items:center;justify-content:space-between;padding:11px 14px;border-bottom:1px solid var(--line)}.recipe-toolbar>div{display:flex;align-items:center;gap:10px}.recipe-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:8px;background:var(--accent-soft);color:var(--accent);font-size:9px;font-weight:800}.recipe-toolbar h2{font-size:16px}.recipe-toolbar small{color:var(--muted);font-size:8px}.recipe-toolbar>div:last-child>a{color:var(--accent);font-size:9px}.recipe-version{padding-right:10px;border-right:1px solid var(--line);text-align:right}.recipe-version b,.recipe-version small{display:block}.recipe-version b{font-size:16px}.builder-layout{display:grid;grid-template-columns:190px minmax(0,1fr)}.builder-index{padding:10px;border-right:1px solid var(--line);background:var(--surface-2)}.builder-index a{display:flex;gap:8px;padding:9px;border-radius:7px}.builder-index a:hover{background:var(--surface)}.builder-index b{width:26px;height:26px;display:grid;place-items:center;border-radius:6px;background:var(--accent-soft);color:var(--accent);font-size:9px}.builder-index strong,.builder-index small{display:block}.builder-index strong{font-size:10px}.builder-index small{color:var(--muted);font-size:8px}.builder-sections{min-width:0}.builder-section{scroll-margin-top:20px;padding:16px;border-bottom:1px solid var(--line)}.builder-section>header{display:flex;align-items:center;gap:9px;margin-bottom:12px}.section-number{width:30px;height:30px;display:grid;place-items:center;border-radius:7px;background:var(--accent);color:#fff;font-size:9px;font-weight:800}.builder-section>header strong,.builder-section>header small{display:block}.builder-section>header strong{font-size:12px}.builder-section>header small{color:var(--muted);font-size:8px}.plan-fields{display:grid;gap:10px}.plan-fields.three{grid-template-columns:1.15fr 1fr .65fr}.plan-fields.two{grid-template-columns:1fr 1fr}.plan-fields.one{margin-top:10px}.plan-fields label{font-size:9px;font-weight:700}.plan-fields input,.plan-fields select{width:100%;display:block;margin-top:4px}.plan-fields label>small,.secret-input small{display:block;margin-top:3px;color:var(--muted);font-size:8px;font-weight:400}.secret-value-control{display:flex;margin-top:4px}.secret-value-control input{flex:1;margin-top:0;border-radius:7px 0 0 7px}.secret-value-control button{border:1px solid var(--line-2);border-left:0;border-radius:0 7px 7px 0;background:var(--surface-2);color:var(--accent);font-size:9px}.security-section{box-shadow:inset 3px 0 0 var(--green)}.validation-note{margin-top:9px;padding:8px;border-radius:6px;background:var(--green-soft);color:var(--green);font-size:8px}.tls-switch{display:flex;align-items:center;gap:8px;margin-bottom:9px;padding:8px;border:1px solid var(--line);border-radius:7px}.tls-switch input{height:auto}.tls-switch strong,.tls-switch small{display:block}.tls-switch small{color:var(--muted);font-size:8px}.builder-actions{position:sticky;bottom:0;z-index:10;display:flex;align-items:center;justify-content:space-between;padding:11px 14px;border-top:1px solid var(--line);background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(12px)}.builder-actions b,.builder-actions small{display:block}.builder-actions b{font-size:10px}.builder-actions small{color:var(--muted);font-size:8px}.builder-actions>div:last-child{display:flex;gap:6px}.node-revision-timeline,.advanced-studio{margin-top:12px;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.advanced-studio>summary{min-height:56px;display:flex;align-items:center;justify-content:space-between;padding:10px 14px}.advanced-studio>summary b,.advanced-studio>summary small{display:block}.advanced-studio>summary b{font-size:11px}.advanced-studio>summary small,.advanced-studio>summary i{color:var(--muted);font-size:8px;font-style:normal}.advanced-studio-body{display:grid;grid-template-columns:200px minmax(400px,1fr) 220px;border-top:1px solid var(--line);background:var(--surface-2)}.field-rail,.official-rail{background:var(--surface)}.field-rail{border-right:1px solid var(--line)}.field-rail>header,.official-rail>header{display:flex;justify-content:space-between;padding:9px;border-bottom:1px solid var(--line);font-size:9px}.field-rail>a{display:grid;grid-template-columns:6px 1fr auto;gap:6px;padding:7px}.field-rail>a.active{background:var(--accent-soft)}.field-rail>a>i{width:5px;height:5px;border-radius:50%;background:var(--line-2)}.field-rail>a>i.present{background:var(--green)}.field-rail strong,.field-rail code{display:block}.field-rail strong{font-size:9px}.field-rail code,.field-rail small{color:var(--muted);font-size:8px}.field-canvas{min-width:0;padding:12px}.field-canvas>header{display:flex;justify-content:space-between}.field-canvas h2{display:inline-block;font-size:15px}.field-canvas header code,.field-canvas header a,.field-canvas>p{color:var(--muted);font-size:8px}.field-canvas>p{margin:8px 0}.field-canvas form textarea{width:100%;min-height:280px;margin-top:4px}.field-canvas form>footer,.source-studio form>footer{display:flex;justify-content:space-between;margin-top:7px}.field-canvas form>footer div,.source-studio form>footer div{display:flex;gap:5px}.source-studio{margin-top:8px;border-top:1px solid var(--line)}.source-studio>summary{padding:9px 0;font-size:9px}.source-studio form>textarea{min-height:400px}.official-rail{border-left:1px solid var(--line)}.official-rail>p,.official-rail summary{padding:8px;border-bottom:1px solid var(--line);font-size:8px}.official-rail a{color:var(--accent)}.official-rail details>div{display:grid;grid-template-columns:1fr 1fr;gap:3px;padding:5px}.official-rail details>div a{padding:5px;background:var(--surface-2);font-size:8px}
`

